interface.definition:
if(ri!showWhen <> false,
  a!localVariables(
    /*DEFAULTS*/
    local!isVerticalTabs: a!defaultValue(value: ri!isVerticalTabs, default: false),
    local!align: a!defaultValue(value: ri!align, default: "START"),
    local!marginBelow: a!defaultValue(value: ri!marginBelow, default: "EVEN_LESS"),

    /*CALC*/
    local!typeButtonsTabs: typeof(ri!buttonTabs),
    local!isTextArrayButtonTabs: local!typeButtonsTabs = typeof({""}),
    local!typeSelectedTab: typeof(ri!selectedTab),
    local!isTextSelectedTab: local!typeSelectedTab = typeof(""),
    local!buttons:
    a!refreshVariable(
      refreshAlways: true,
      value: 
      #"SYSTEM_SYSRULES_forEach"(
        items: ri!buttonTabs,
        expression: 
        if(local!isTextArrayButtonTabs,
          #"SYSTEM_SYSRULES_buttonWidget_v1"(
            label: fv!item,
            loadingIndicator: true,
            size: ri!size,
            style: 
            if(ri!selectedTab = fv!item,
              "SOLID",
              "LINK"
            ),
            value: fv!item,
            saveInto: {
              a!save(ri!selectedTab, tostring(fv!item)),
              ri!saveInto
            }
          ),
          /*OR IS TYPE OF 'type!{urn:com:appian:types:IEM_ICO}IEM_ICO_UTY_ButtonTab'()*/
          #"SYSTEM_SYSRULES_buttonWidget_v1"(
            label: fv!item.label,
            icon: fv!item.icon,
            iconPosition: fv!item.iconPosition,
            submit: fv!item.isSubmit,
            loadingIndicator: true,
            disabled: fv!item.isDisabled,
            size: fv!item.size,
            width: fv!item.width,
            color: fv!item.color,
            style: 
            if(local!isTextSelectedTab,
              if( 
                ri!selectedTab = fv!item.label,
                "SOLID",
                "LINK"
              ),
              if(cast('type!{urn:com:appian:types:IEM_ICO}IEM_ICO_UTY_ButtonTab', ri!selectedTab) = fv!item,
                "SOLID",
                "LINK"
              )
            ),
            value: fv!item.label,
            saveInto: {
              a!save(ri!selectedTab, fv!item),
              ri!saveInto
            },
            validate: fv!item.isValidate,
            validationGroup: fv!item.validationGroup,
            showWhen: fv!item.showWhen
          )
        )
      )
    ),

    /*DISPLAY*/
    if(ri!isVerticalTabs,
      #"SYSTEM_SYSRULES_forEach"(
        items: local!buttons,
        expression: {
          #"SYSTEM_SYSRULES_ButtonArrayLayout"(
            align: local!align,
            buttons: fv!item,
            marginBelow: "NONE"
          )
        }
      ),
      #"SYSTEM_SYSRULES_ButtonArrayLayout"(
        marginBelow: ri!marginBelow,
        align: local!align,
        buttons: local!buttons
      )
    )
  ), {}
)
